window.toggleSidebarSection = function(id){if(window.APS && APS.toggleSection)return APS.toggleSection(id);var ul = document.getElementById(id);if(!ul)return;var hidden = ul.style.display === 'none';ul.style.display = hidden ? '':'none';var arrow = document.getElementById('arrow-' + id);if(arrow)arrow.classList.toggle('collapsed',!hidden);var saved = localStorage.getItem('adminSidebarSections');var state = saved ? JSON.parse(saved):{};state[id] = hidden;localStorage.setItem('adminSidebarSections',JSON.stringify(state));};window.toggleAllSidebarSections = function(){if(window.APS && APS.toggleAllSections)return APS.toggleAllSections();var menus = document.querySelectorAll('.sidebar-menu[id]');var anyHidden = Array.from(menus).some(function(el){return el.style.display === 'none';});menus.forEach(function(el){el.style.display = anyHidden ? '':'none';var saved = localStorage.getItem('adminSidebarSections');var state = saved ? JSON.parse(saved):{};state[el.id] = anyHidden;localStorage.setItem('adminSidebarSections',JSON.stringify(state));});document.querySelectorAll('.sidebar-sec-arrow[id^="arrow-sec-"]').forEach(function(arr){arr.classList.toggle('collapsed',!anyHidden);});};document.addEventListener('DOMContentLoaded',function(){if(window.APS && APS._init)return;var saved = localStorage.getItem('adminSidebarSections');if(!saved)return;try{var state = JSON.parse(saved);Object.keys(state).forEach(function(id){var ul = document.getElementById(id);var arrow = document.getElementById('arrow-' + id);if(ul)ul.style.display = state[id] ? '':'none';if(arrow)arrow.classList.toggle('collapsed',!state[id]);});}catch(e){}});document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.alert-dismissible').forEach(function(alert){setTimeout(function(){var close = alert.querySelector('.btn-close');if(close)close.click();},5000);});});document.addEventListener('DOMContentLoaded',function(){var path = window.location.pathname;document.querySelectorAll('.sidebar-link').forEach(function(link){if(link.getAttribute('href')=== path){link.classList.add('active');var parent = link.closest('.sidebar-menu');if(parent)parent.style.display = '';}});});